"""Fill the validation table only from completed, hashed run records."""
import hashlib,json,pathlib,re
here=pathlib.Path(__file__).resolve().parent;root=here.parents[4]
runs={r['name']:r for r in map(json.loads,(here/'runs.jsonl').read_text().splitlines())}
def counts(name):
 r=runs[name];raw=(here/(name+'.log')).read_bytes();assert hashlib.sha256(raw).hexdigest()==r['sha256']
 return {k:int(v) for k,v in re.findall(r'^# (tests|pass|fail|skipped|cancelled) (\d+)$',raw.decode(),re.M)}
final=counts('delivery-node22-serial');assert final=={'tests':519,'pass':517,'fail':0,'skipped':2,'cancelled':0},final
requirements={'original-h01-configured-owner-bound':(22,22,0),'original-faults-owner-bound':(49,49,0),'round2-storage-owner-bound':(14,14,0),'round2-cache-owner-bound':(8,8,0),'round2-ack-owner-bound':(1,1,0),'round3-original-adversarial-owner-bound':(8,7,1),'round3-original-metadata-owner-bound':(2,2,0),'round3-controls-backup-owner-bound':(3,3,0),'contracts-owner-bound':(22,22,0)}
for name,(total,passed,failed) in requirements.items():
 c=counts(name);assert (c['tests'],c['pass'],c['fail'])==(total,passed,failed),(name,c)
 assert runs[name]['exitCode']==(1 if failed else 0)
assert 'not ok 3 - native candidate proof remains valid through before-ack' in (here/'round3-original-adversarial.log').read_text()
